func GetOEISLookupSequence(id string, name string, maxNumber *big.Int, isPositional bool) (*NumericSequence, error) {
	data, ok := oeisLookups[id]
	if !ok {
		return nil, fmt.Errorf("lookup for %s not found", id)
	}

	if isPositional {
		if maxNumber.Sign() <= 0 || !maxNumber.IsInt64() || maxNumber.Int64() > int64(len(data)) {
			return nil, fmt.Errorf("position out of lookup range")
		}
		val := new(big.Int)
		val.SetString(data[maxNumber.Int64()-1], 10)
		return &NumericSequence{
			Name:     fmt.Sprintf("%s (%s)", name, id),
			Number:   maxNumber,
			Sequence: []*big.Int{val},
			Result:   val,
		}, nil
	}

	limit := int64(len(data))
	if maxNumber.IsInt64() && maxNumber.Int64() < limit {
		limit = maxNumber.Int64()
	}

	var sequence []*big.Int
	for i := int64(0); i < limit; i++ {
		val := new(big.Int)
		val.SetString(data[i], 10)
		sequence = append(sequence, val)
	}

	var result *big.Int
	if len(sequence) > 0 {
		result = sequence[len(sequence)-1]
	} else {
		result = big.NewInt(0)
	}

	return &NumericSequence{
		Name:     fmt.Sprintf("%s (%s)", name, id),
		Number:   maxNumber,
		Sequence: sequence,
		Result:   result,
	}, nil
}
